/**
 * Creates a minimal ClassInfo from ClassName.
 * In pitest 1.10.0+, CoverageDatabase.getClassInfo() was removed,
 * so we create ClassInfo directly.
 */
private Set<ClassInfo> createClassInfoFromName(ClassName className) {
  // Create a minimal ClassInfo using reflection-free approach
  // ClassInfo requires ClassPointer for superClass and outerClass, and ClassInfoBuilder
  // Since we only need getName() from ClassInfo, we create a minimal instance
  ClassIdentifier id = new ClassIdentifier(0L, className);
  ClassPointer superClassPointer = new ClassPointer() {
    @Override
    public Optional<ClassInfo> fetch() {
      return Optional.empty();
    }
  };
  ClassPointer outerClassPointer = new ClassPointer() {
    @Override
    public Optional<ClassInfo> fetch() {
      return Optional.empty();
    }
  };

  // We need to use reflection to create ClassInfo since the constructor is package-private
  // Actually, looking at the bytecode, the constructor is public but requires ClassInfoBuilder
  // Let's create a ClassInfoBuilder-like object
  try {
    java.lang.reflect.Constructor<ClassInfo> constructor = ClassInfo.class.getDeclaredConstructor(
        ClassPointer.class, ClassPointer.class,
        org.pitest.classinfo.ClassInfoBuilder.class
    );
    constructor.setAccessible(true);

    org.pitest.classinfo.ClassInfoBuilder builder = new org.pitest.classinfo.ClassInfoBuilder(id);
    ClassInfo classInfo = constructor.newInstance(superClassPointer, outerClassPointer, builder);
    return Collections.singleton(classInfo);
  } catch (Exception e) {
    throw new RuntimeException("Failed to create ClassInfo", e);
  }
}

