  private final Set<ClassName>             classes   = new HashSet<>();

  public MutationTestSummaryData(final String fileName,
      final Collection<MutationResult> results, final Collection<ClassName> classes) {
    this.fileName = fileName;
    this.mutations.addAll(results);
    this.classes.addAll(classes);
  }

